# -*- coding: utf-8 -*-
"""Contenido de la guía: itinerario, alojamiento, info práctica, historia, vocabulario."""

def stop(time, name, desc, tag=None, included=True, curio=None, mapq=None, nearby=None, more=None, photos=None, tips=None):
    return dict(time=time, name=name, desc=desc, tag=tag, included=included, curio=curio,
                mapq=mapq, nearby=nearby, more=more, photos=photos or [], tips=tips or [])

